<?php require dirname(__DIR__).'/lib.php';admin_required();if($_SERVER['REQUEST_METHOD']!=='POST'){http_response_code(405);exit;}try{check_csrf();$id=filter_var($_POST['id']??null,FILTER_VALIDATE_INT);$status=(string)($_POST['status']??'');if(!$id||!in_array($status,['received','shipped'],true))throw new RuntimeException('잘못된 요청');$st=db()->prepare('UPDATE apple_orders SET status=?,shipped_at=IF(?="shipped",NOW(),NULL) WHERE id=?');$st->execute([$status,$status,$id]);$_SESSION['apple_flash']='배송상태를 변경했습니다.';}catch(Throwable $e){$_SESSION['apple_flash']='변경에 실패했습니다.';}header('Location: index.php');exit;
